function medicalHTML(){const ps=roster(G.user),inj=ps.filter(p=>p.inj>0).sort((a,b)=>b.o-a.o),fr=ps.filter(p=>p.fragile&&p.inj<=0),tired=ps.filter(p=>p.inj<=0&&p.energy<65),heavy=ps.filter(p=>p.inj<=0&&(p.ld||0)>28).sort((a,b)=>b.ld-a.ld),docs=staffOf(G.user,'DOC'),F=staffFx(),lvl=docs.length?Math.round(avg(docs.map(x=>x.r.med))):0,t=G.teams[G.user],hc=lum(t.c1)>.85?t.c2:t.c1;
  const riskC=x=>x<.15?'g':x<.35?'y':'r';
  const rows=inj.map(p=>{const T=injTotal(p),s=p.injS||'min',O=earlyOpts(p),done=clamp((T-p.inj)/T*100,0,100);
    return `<article class="md-p"><span class="avatar ph" style="width:60px;height:60px;flex:none;box-shadow:none">${avatarIn(p,p.no)}</span><div class="md-b"><div class="md-top"><b>${esc(pname(p))}</b><em class="md-s ${s}">${INJS[s].n}</em>${p.fragile?'<em class="md-s mod">Setback risk</em>':''}</div><small>${p.pos} · OVR ${ovrTxt(p)} · ${esc(p.injT||'Knock')}</small>
    <div class="md-bar"><i style="width:${done}%;background:${hc}"></i></div><small class="md-eta">Out for about <b>${p.inj}</b> game${p.inj>1?'s':''}</small>
    <div class="md-o">${O.length?O.map(o=>`<button class="md-btn" data-act="medearly:${p.id}:${o.cut}"><span>${o.left?`${o.cut} game${o.cut>1?'s':''} earlier`:'Back for the next game'}</span><em class="${riskC(o.total)}">${Math.round(o.total*100)}% setback risk</em></button>`).join(''):`<p class="md-no">${s==='sev'?'The doctors will not allow an earlier return yet.':'No shortcut available.'}</p>`}</div></div></article>`;}).join('');
  const chip=(p,txt)=>`<div class="md-c"><span class="avatar ph" style="width:38px;height:38px;flex:none;box-shadow:none">${avatarIn(p,p.no)}</span><span class="md-cn"><b>${esc(pname(p))}</b><small>${txt}</small></span>${ebar(p.energy)}</div>`;
  return `<div class="stack"><section class="md"><header class="md-h" style="--md1:${hc}"><span class="md-ic">${IC.med}</span><div class="md-t"><small>${esc(t.name)}</small><b>Medical centre</b></div><div class="md-st"><div><b>${inj.length}</b><small>Injured</small></div><div><b>${fr.length}</b><small>Fragile</small></div><div><b>${docs.length?lvl:'–'}</b><small>Medical staff</small></div></div></header>
  <div class="md-l">${rows||'<div class="md-e"><b>Nobody is injured</b><p>The whole squad is available.</p></div>'}</div>
  <p class="md-f">A player brought back early plays six games below his best and can break down again, for longer than the first time. ${docs.length?`Your ${docs.length>1?`${docs.length} medical staff change`:'medical staff member changes'} injury risk by ×${F.injury.toFixed(2)}.`:'You have no medical staff, so the risk is at its highest.'} ${jokerNeed().length?'Out for 6 games or more? You can sign a medical joker from the free agents.':''}</p></section>
  ${fr.length||tired.length?`<div class="g-2">${fr.length?card('Back early',fr.map(p=>chip(p,`${p.fragile.left} game${p.fragile.left>1?'s':''} of risk left`)).join('')):''}${tired.length?card('Tired',tired.map(p=>chip(p,`Injury risk ×${fatigueRisk(p.energy)}`)).join('')):''}</div>`:''}${heavy.length?card('Heavy minutes',`<p class="mut" style="margin:0 0 10px">Recent workload and age raise the injury risk. Players over 30 also recover more slowly between games.</p>`+heavy.map(p=>chip(p,`${Math.round(p.ld)} min a game lately \u00b7 age ${p.age} \u00b7 risk \u00d7${(loadInj(p.ld)*ageInj(p.age||27)).toFixed(1)}`)).join('')):''}</div>`;}

