    <div class="ntms">${meter('Team strength',S.toFixed(1),'',(S-55)*3)}${meter('Average age',age)}${meter('Guards · Forwards · Centres',`${pg('G')} · ${pg('F')} · ${pg('C')}`)}${meter(cmp||st==='pre'?'Naturalised players on the list':'Naturalised player',`${nz.length} / ${cmp||st==='pre'?2:1}`,nz.length?esc(pname(nz[0])):'none')}</div>
