function crunchHTML(M){const m=M.m,ui=m.s[0].tid===(m.ntU!=null?m.ntU:G.user)?0:1;if(!m.crunch())return '';const me=m.s[ui],opp=m.s[1-ui],diff=me.pts-opp.pts,armed=m.play[ui];
  const who=k=>{const p=m.playPick(me,k);return p?` \u00b7 ${sname(p)}`:'';};
  const hot=m.run_[1-ui]>=6?`<p style="font-size:13.5px"><span class="pill r">${esc(G.teams[opp.tid].short)} on a ${m.run_[1-ui]}-0 run</span> A timeout now helps most.</p>`:'';
  const plays=Object.keys(LIVEPLAY).map(k=>`<button class="btn sm${armed===k?' p':''}" data-act="lplay:${k}" title="${esc(LIVEPLAY[k].d)}">${LIVEPLAY[k].n}${who(k)}${m.lastPlay[ui]===k?' \u00b7 they know it':''}</button>`).join('');
  const canFoul=m.clock<=60&&diff<0;
  return `<div class="sec"><div class="lbl">Crunch time \u00b7 ${diff>0?`up ${diff}`:diff<0?`down ${-diff}`:'tied'}</div>${hot}${M.paused?'<div class="btns" style="margin-bottom:8px"><button class="btn sm p" data-act="pause">Continue the game</button></div>':''}<p class="mut" style="font-size:13px;margin-bottom:6px">Next attack${armed?`: ${LIVEPLAY[armed].n}`:''}</p><div style="display:grid;gap:6px;grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">${plays}</div>${m.clock<=60?`<p class="mut" style="font-size:13px;margin:10px 0 6px">Defense</p><div class="btns"><button class="btn sm${m.foul[ui]?' p':''}" data-act="lfoul" ${canFoul?'':'disabled'}>${m.foul[ui]?'Foul ordered':'Foul on purpose'}</button></div><p class="mut" style="font-size:13px">${canFoul?'Stops the clock on their next attack. They shoot two free throws, usually their weakest shooter.':'Only when you are behind.'}</p>`:''}</div>`;}
// the game stops by itself when crunch time starts, and before every attack in a close finish
function crunchStop(M){const m=M.m;if(m.done||m.q<4)return false;const d=Math.abs(m.s[0].pts-m.s[1].pts);
  if(!M.cr1&&m.clock<=120&&d<=10){M.cr1=true;return true;}
  return m.clock<=30&&d<=6;}
function startTimer(){const M=UI.match;clearInterval(M.timer);if(M.paused||M.m.done)return;M.timer=setInterval(()=>{const m=M.m;m.step();if(m.done){clearInterval(M.timer);render();}else if(m.halt){const t=m.halt;m.halt=null;clearInterval(M.timer);M.paused=true;M.crH=null;M.why=`${t}. Check your line-up, then play on.`;render();}else if(crunchStop(M)){clearInterval(M.timer);M.paused=true;M.crH=null;render();}else updMatch();},SPEED[M.speed]);}
