  trprot(a){const M=UI.modal;if(!M||M.done)return;const [id,N]=a.split(':');M.x=M.x||{prot:{},sw:[]};M.x.prot[+id]=+N;render();},
  trsw(a){const M=UI.modal;if(!M||M.done)return;const [y,hh]=a.split(':');M.x=M.x||{prot:{},sw:[]};const i=M.x.sw.findIndex(x=>x.y===+y&&x.h===hh);if(i>=0)M.x.sw.splice(i,1);else{M.x.sw=M.x.sw.filter(x=>x.y!==+y);M.x.sw.push({y:+y,h:hh});}render();},
  trgo(){const M=UI.modal;if(!M)return;TRX=M.x||null;const r=proposeTrade(M.tid,M.give,M.get,M.gpk,M.tpk);TRX=null;if(r.done){M.done=`Trade done with the ${G.teams[M.tid].name}.`;}else toast(r.why);render();},
  trpk(a){const M=UI.modal;if(!M||M.done)return;const [side,id]=a.split(':'),k=side==='get'?'tpk':'gpk',n=+id;M[k]=(M[k]||[]).includes(n)?M[k].filter(x=>x!==n):(M[k]||[]).concat([n]);render();},
  dboard(id){const D=G.draft;if(!D||!userNBA())return;id=+id;D.board=D.board.includes(id)?D.board.filter(x=>x!==id):D.board.concat([id]);save();render();},
