/* ===================== National team squad during the window (like the club squad page) ===================== */
// Call-ups close when the window starts; then the twelve are set and the coach orders them: five starters, seven off the bench.
const NT_MIN=[30,28,28,26,26,16,14,12,10,6,4,0];
function ntRotHTML(){const J=G.nt.job,c=J.c,w=ntPend(),C=G.nt.cyc,key=ntKey(w),ps=ntUserSquad(c,ntWinF(w),key),[hc]=NT_COL[c]||['#1f4fd1'];
  if(UI.ntSel==null||!ps.find(p=>p.id===UI.ntSel))UI.ntSel=ps[0]&&ps[0].id;const sel=G.players[UI.ntSel],plan={};ps.forEach((p,i)=>plan[p.id]=NT_MIN[i]||0);
  const tm=p=>p.tid!=null?G.teams[p.tid]:null;
  const tag=p=>p.inj>0?`<i class="sq-t r">Inj ${p.inj}</i>`:ntIsNat(p)?'<i class="sq-t y">NAT</i>':'';
  const en=p=>`<span class="sq-en"><i style="width:${Math.round(p.energy)}%;background:${p.energy>=70?'#3ecb7c':p.energy>=45?'#e0a400':'#ff5a52'}"></i></span>`;
  const on=p=>`${UI.ntSel===p.id?' on':''}${UI.ntSwap===p.id?' sw':''}`;
  const row=p=>`<button class="sq-r${on(p)}" draggable="true" data-pid="${p.id}" data-act="ntsel:${p.id}"><span class="sq-no">${p.no}</span><span class="avatar ph sq-ph">${avatarIn(p,p.no)}</span><span class="sq-nm"><b>${esc(pname(p))}</b>${tag(p)}</span><span class="sq-pos">${p.pos}</span>${ovb(ovrEst(p))}${en(p)}</button>`;
  const grp=(l,x)=>`<div class="sq-g">${l}</div>${x.map(row).join('')}`;
  const SPOT=[['PG',50,80],['SG',17,50],['SF',83,50],['PF',32,21],['C',68,21]];
  const spot=(p,i)=>{if(!p)return '';const [k,x,y]=SPOT[i];return `<button class="sq-s${on(p)}${p.inj>0?' inj':''}" style="left:${x}%;top:${y}%" draggable="true" data-pid="${p.id}" data-act="ntsel:${p.id}"><span class="avatar ph sq-sph">${avatarIn(p,p.no)}</span><span class="sq-sc"><span class="sq-sh"><em class="${p.pos===k?'':'off'}">${p.pos}</em>${ovb(ovrEst(p))}</span><b>${esc(sname(p))}</b><small>${plan[p.id]} min</small></span></button>`;};
  const bc=p=>`<button class="sq-b${on(p)}${p.inj>0?' inj':''}" draggable="true" data-pid="${p.id}" data-act="ntsel:${p.id}"><span class="avatar ph sq-bph">${avatarIn(p,p.no)}</span><span class="sq-sh"><em>${p.pos}</em>${ovb(ovrEst(p))}</span><b>${esc(sname(p))}</b><small>${plan[p.id]} min</small></button>`;
  const ch=ntChem(),t=sel?tm(sel):null,i=sel?ps.indexOf(sel):-1;
  const panel=sel?`<div class="ntd"><div class="ntd-ph">${avatarIn(sel,sel.no)}</div><b>${esc(pname(sel))}</b><small>${sel.pos} · ${sel.age} · ${ht(sel.ht)}</small><small>${t?`${mini(t)} ${esc(t.name)}`:esc(sel.ntClub||'Free agent')}</small>
    <div class="ntd-k"><div><small>OVR</small><b>${ovrEst(sel)}</b></div><div><small>Energy</small><b>${Math.round(sel.energy)}%</b></div><div><small>Caps</small><b>${sel.ntc||0}</b></div><div><small>Role</small><b>${i<5?'Starter':i<9?'Rotation':'Bench'}</b></div></div>
    ${ntIsNat(sel)?'<p class="mut" style="font-size:12.5px">Naturalised player: the one allowed in this squad.</p>':''}
    <div class="btns">${i>=5?`<button class="btn sm p" data-act="ntstart:${sel.id}">Make starter</button>`:`<button class="btn sm" data-act="ntbench:${sel.id}">To the bench</button>`}<button class="btn sm" data-act="ntswap:${sel.id}">Swap with\u2026</button><button class="btn sm" data-act="prof:${sel.id}">Profile</button></div></div>`:'';
  return `<div class="ntlock"><span>${ntFlag(c,28)}</span><div><b>Call-ups closed</b><small>The twelve for the ${esc(w.tour?w.name:w.lbl)} are with the team. Set your starting five and rotation.</small></div></div>
  <div class="sq" style="--sq1:${hc}"><section class="sq-c sq-l"><header class="sq-h"><div><b>${esc(ntName(c))}</b><em>${ps.length}/12</em></div></header><div class="sq-th"><span>#</span><span></span><span>Player</span><span>Pos</span><span>Ovr</span><span>Energy</span></div><div class="sq-list">${grp('Starters',ps.slice(0,5))}${grp('Bench',ps.slice(5))}</div></section>
  <section class="sq-c sq-m"><header class="sq-h"><div><b>Rotation builder</b></div><span class="sq-ch"><span>Chemistry</span><i class="sq-cb"><u style="width:${ch}%;background:${chemCol(ch)}"></u></i><b>${ch}</b></span></header>
  ${UI.ntSwap!=null&&G.players[UI.ntSwap]?`<div class="sq-swap">Pick who swaps places with ${esc(sname(G.players[UI.ntSwap]))} <button data-act="ntswap:">Cancel</button></div>`:''}
  <div class="sq-court"><svg viewBox="0 0 800 560" preserveAspectRatio="none" aria-hidden="true"><g fill="none" stroke="var(--or)" stroke-opacity=".38" stroke-width="3"><rect x="30" y="16" width="740" height="528" rx="4"/><rect x="290" y="16" width="220" height="210"/><circle cx="400" cy="226" r="74"/><path d="M90 16v110c0 190 130 280 310 280s310-90 310-280V16"/><path d="M300 544a100 100 0 0 1 200 0"/></g></svg><span class="sq-wm">${esc(ntName(c))}</span>${ps.slice(0,5).map(spot).join('')}</div>
  <div class="sq-bh"><b>Bench</b><span>Planned 200 min · a FIBA game has 200</span></div><div class="sq-bg">${ps.slice(5).map(bc).join('')}</div>
  <div class="sq-act"><button class="sq-btn" data-act="ntautorot">Auto-pick rotation</button><p>Drag a player onto another to swap them, or use Swap with\u2026 in the player panel. Changes save by themselves.</p></div></section>
  <section class="sq-c sq-d">${panel}</section></div>`;}

/* ===================== Boot ===================== */
function boot(data){if(location.hash==='#nt-eb'){document.getElementById('app').innerHTML='<div style="padding:60px 20px;text-align:center;font:600 18px var(--fb)">Preparing the EuroBasket demo\u2026</div>';setTimeout(()=>{try{ntDemo('eb');UI.view='main';UI.tab='home';}catch(e){console.error(e);}render();window.scrollTo(0,0);},60);return;}if(location.hash==='#nt-og'){document.getElementById('app').innerHTML='<div style="padding:60px 20px;text-align:center;font:600 18px var(--fb)">Preparing the Olympic summer demo\u2026</div>';setTimeout(()=>{try{ntDemo('og');UI.view='main';UI.tab='home';}catch(e){console.error(e);}render();window.scrollTo(0,0);},60);return;}if(location.hash==='#nt-tour'){document.getElementById('app').innerHTML='<div style="padding:60px 20px;text-align:center;font:600 18px var(--fb)">Preparing the World Cup demo\u2026</div>';setTimeout(()=>{try{ntDemo('tour');UI.view='main';UI.tab='home';}catch(e){console.error(e);}render();window.scrollTo(0,0);},60);return;}if(location.hash==='#nt-window'){document.getElementById('app').innerHTML='<div style="padding:60px 20px;text-align:center;font:600 18px var(--fb)">Preparing the international window demo\u2026</div>';setTimeout(()=>{try{ntDemo('win');UI.view='main';UI.tab='home';}catch(e){console.error(e);}render();window.scrollTo(0,0);},60);return;}if(location.hash==='#nt-demo'){document.getElementById('app').innerHTML='<div style="padding:60px 20px;text-align:center;font:600 18px var(--fb)">Preparing the Bosnia national team demo\u2026</div>';setTimeout(()=>{try{ntDemo();UI.view='main';UI.tab='comp';UI.comp='nt';UI.ntSub='m';}catch(e){console.error(e);}render();},60);return;}if(data&&data.G){G=data.G;ensureStaff();ensureFinance();ensureSponsors();ensureDomestic();normSquads();Object.assign(UI,data.UI||{});UI.match=null;UI.modal=null;if(UI.view==='match')UI.view='main';}render();}
try{window.claude?.hot?.snapshot?.(()=>({G,UI:{...UI,match:null,modal:null}}));}catch(e){}
window.claude?.hot?.ready?window.claude.hot.ready(boot):boot(window.claude?.hot?.data??{});
try{SAVE_READY.then(()=>{if(SAVE_TXT&&(!G||UI.view==='start'))render();});}catch(e){}

